package com.shahboun.aqim;

import android.util.Base64;import org.json.*;import java.io.*;import java.util.*;import java.util.zip.GZIPInputStream;

public final class LibyaPrayerCalibration{
 private LibyaPrayerCalibration(){}
 private static JSONObject model;
 private static final String DATA="";
 private static synchronized JSONObject load(){if(model!=null)return model;try{byte[] gz=Base64.decode(DATA,Base64.DEFAULT);GZIPInputStream in=new GZIPInputStream(new ByteArrayInputStream(gz));ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))>0)out.write(b,0,n);model=new JSONObject(out.toString("UTF-8"));}catch(Exception e){model=new JSONObject();}return model;}
 private static double km(double a,double o,double b,double p){double r=6371,da=Math.toRadians(b-a),dl=Math.toRadians(p-o);double x=Math.sin(da/2)*Math.sin(da/2)+Math.cos(Math.toRadians(a))*Math.cos(Math.toRadians(b))*Math.sin(dl/2)*Math.sin(dl/2);return 2*r*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
 public static boolean isLibya(double lat,double lon){return lat>=19&&lat<=34&&lon>=9&&lon<=26;}
 public static LinkedHashMap<String,Calendar> apply(Calendar day,double lat,double lon,LinkedHashMap<String,Calendar> base){if(base==null||!isLibya(lat,lon))return base;try{JSONObject all=load();Iterator<String> it=all.keys();JSONObject best=null;double bd=1e9;while(it.hasNext()){JSONObject c=all.getJSONObject(it.next());double d=km(lat,lon,c.getDouble("lat"),c.getDouble("lon"));if(d<bd){bd=d;best=c;}}if(best==null||bd>220)return base;JSONArray month=best.getJSONArray("m").getJSONArray(day.get(Calendar.MONTH));String[] names={"الفجر","الشروق","الظهر","العصر","المغرب","العشاء"};for(int i=0;i<names.length;i++){Calendar c=base.get(names[i]);if(c!=null)c.add(Calendar.MINUTE,month.getInt(i));}Calendar set=base.get("الغروب"),mag=base.get("المغرب");if(set!=null&&mag!=null)set.setTimeInMillis(mag.getTimeInMillis());return base;}catch(Exception e){return base;}}
}
